-- 冻结兼容基线 pre-lifecycle-v1；仅用于门禁随机数据库，禁止执行于业务库。
-- 基于接入统一生命周期前的完整结构，保留已支持补列的旧形态；未来新增字段须有升级路径。
-- 本文件不随 database gate --refresh-contract 更新，禁止以新装结构覆盖历史基线。
CREATE SEQUENCE seq_quality_issue INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 1 NO CYCLE;;
CREATE SEQUENCE seq_task_log INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 1 NO CYCLE;;
CREATE SEQUENCE seq_update_log INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 1 NO CYCLE;;
CREATE TABLE app_config("key" VARCHAR PRIMARY KEY, "value" VARCHAR, updated_at TIMESTAMP);;
CREATE TABLE async_task(id VARCHAR PRIMARY KEY, task_type VARCHAR, params VARCHAR, status VARCHAR, progress DOUBLE, message VARCHAR, result VARCHAR, trigger_source VARCHAR, job_id VARCHAR, job_name VARCHAR, chain_id VARCHAR, parent_task_id VARCHAR, trigger_event_id VARCHAR, retry_count INTEGER, execution_attempt INTEGER, cancel_requested_at TIMESTAMP, created_at TIMESTAMP, updated_at TIMESTAMP);;
CREATE TABLE backtest_equity(run_id VARCHAR, trade_date DATE, equity DOUBLE, cash DOUBLE, position_value DOUBLE, n_positions INTEGER, drawdown DOUBLE, benchmark_equity DOUBLE, PRIMARY KEY(run_id, trade_date));;
CREATE TABLE backtest_metrics(run_id VARCHAR PRIMARY KEY, total_return DOUBLE, annual_return DOUBLE, max_drawdown DOUBLE, max_dd_days INTEGER, annual_vol DOUBLE, sharpe DOUBLE, calmar DOUBLE, sortino DOUBLE, win_rate DOUBLE, profit_factor DOUBLE, avg_hold_days DOUBLE, n_trades INTEGER, benchmark_return DOUBLE, excess_return DOUBLE, hit_rate_by_grade VARCHAR, extra VARCHAR);;
CREATE TABLE backtest_run(id VARCHAR PRIMARY KEY, kind VARCHAR, profile_id VARCHAR, model_id VARCHAR, score_profile_id VARCHAR, trade_profile_id VARCHAR, score_profile_version INTEGER, profile_version INTEGER, trade_profile_version INTEGER, signature VARCHAR, date_start DATE, date_end DATE, params VARCHAR, status VARCHAR, detail VARCHAR, created_at TIMESTAMP, finished_at TIMESTAMP);;
CREATE TABLE backtest_trade(run_id VARCHAR, seq INTEGER, code VARCHAR, entry_date DATE, entry_price DOUBLE, exit_date DATE, exit_price DOUBLE, exit_reason VARCHAR, exit_detail VARCHAR, shares BIGINT, return_pct DOUBLE, pnl DOUBLE, hold_days INTEGER, grade VARCHAR, entry_score DOUBLE, entry_rank INTEGER, entry_pick_rank INTEGER, entry_pool INTEGER, PRIMARY KEY(run_id, seq));;
CREATE TABLE board_bar(board_code VARCHAR, trade_date DATE, open DOUBLE, high DOUBLE, low DOUBLE, "close" DOUBLE, volume DOUBLE, amount DOUBLE, PRIMARY KEY(board_code, trade_date));;
CREATE TABLE board_dict(board_code VARCHAR PRIMARY KEY, app_code VARCHAR, "name" VARCHAR NOT NULL, board_type VARCHAR NOT NULL, "source" VARCHAR DEFAULT('ths') NOT NULL, has_members BOOLEAN DEFAULT(CAST('f' AS BOOLEAN)), has_bar BOOLEAN DEFAULT(CAST('f' AS BOOLEAN)), has_fund_flow BOOLEAN DEFAULT(CAST('f' AS BOOLEAN)), member_count BIGINT, member_history_start_date DATE, member_snapshot_at TIMESTAMP, last_seen_at DATE, updated_at TIMESTAMP);;
CREATE TABLE board_fund_flow(board_code VARCHAR, snapshot_date DATE, period VARCHAR, inflow DOUBLE, outflow DOUBLE, net_inflow DOUBLE, net_ratio DOUBLE, leader_stock VARCHAR, leader_pct DOUBLE, PRIMARY KEY(board_code, snapshot_date, period));;
CREATE TABLE board_member(board_code VARCHAR, code VARCHAR, first_seen_date DATE, PRIMARY KEY(board_code, code));;
CREATE TABLE daily_bar(code VARCHAR, trade_date DATE, open DOUBLE, high DOUBLE, low DOUBLE, "close" DOUBLE, pre_close DOUBLE, volume BIGINT, amount DOUBLE, adj_factor DOUBLE, adj_factor_clean DOUBLE, turnover_rate DOUBLE, is_st BOOLEAN, is_suspended BOOLEAN, limit_status TINYINT, is_one_word BOOLEAN, PRIMARY KEY(code, trade_date));;
CREATE TABLE daily_metrics(code VARCHAR, trade_date DATE, float_mv DOUBLE, total_mv DOUBLE, total_mv_source VARCHAR, float_mv_source VARCHAR, reported_total_mv DOUBLE, reported_total_mv_source VARCHAR, reported_total_close DOUBLE, reported_float_mv DOUBLE, reported_float_mv_source VARCHAR, reported_float_close DOUBLE, PRIMARY KEY(code, trade_date));;
CREATE TABLE data_dimension_registry(dimension VARCHAR PRIMARY KEY, name_cn VARCHAR, status VARCHAR, "source" VARCHAR, "tables" VARCHAR, descr VARCHAR);;
CREATE TABLE data_quality_issue(id BIGINT, code VARCHAR, trade_date DATE, issue_type VARCHAR, severity VARCHAR, status VARCHAR, detail VARCHAR, detected_at TIMESTAMP, resolved_at TIMESTAMP, fix_task_id VARCHAR, ignore_scope VARCHAR, ignore_active BOOLEAN);;
CREATE TABLE data_source_provenance(code VARCHAR, table_name VARCHAR, date_start DATE, date_end DATE, "source" VARCHAR, "rows" INTEGER, fetched_at TIMESTAMP);;
CREATE TABLE data_update_log(id BIGINT, table_name VARCHAR, "source" VARCHAR, date_start DATE, date_end DATE, row_count BIGINT, status VARCHAR, detail VARCHAR, updated_at TIMESTAMP);;
CREATE TABLE index_bar(index_code VARCHAR, trade_date DATE, open DOUBLE, high DOUBLE, low DOUBLE, "close" DOUBLE, volume BIGINT, amount DOUBLE, PRIMARY KEY(index_code, trade_date));;
CREATE TABLE indicator_def("key" VARCHAR PRIMARY KEY, name_cn VARCHAR, category VARCHAR, dtype VARCHAR, direction VARCHAR, kind VARCHAR, expression VARCHAR, params VARCHAR, categories VARCHAR, layer VARCHAR, parent_key VARCHAR, preset_params VARCHAR, enabled BOOLEAN, is_builtin BOOLEAN, descr VARCHAR, created_at TIMESTAMP, updated_at TIMESTAMP);;
CREATE TABLE layout_field_policy(component_kind VARCHAR, field VARCHAR, allowed_layers VARCHAR, updated_at TIMESTAMP, PRIMARY KEY(component_kind, field));;
CREATE TABLE layout_page_config(page_key VARCHAR PRIMARY KEY, preset_key VARCHAR, config VARCHAR, schema_version INTEGER, updated_at TIMESTAMP);;
CREATE TABLE layout_preset("key" VARCHAR PRIMARY KEY, "name" VARCHAR, description VARCHAR, config VARCHAR, enabled BOOLEAN, is_builtin BOOLEAN, schema_version INTEGER, created_at TIMESTAMP, updated_at TIMESTAMP);;
CREATE TABLE layout_user_config(user_id VARCHAR, page_key VARCHAR, config VARCHAR, schema_version INTEGER, updated_at TIMESTAMP, PRIMARY KEY(user_id, page_key));;
CREATE TABLE limit_ladder_invalidation_outbox(event_id VARCHAR PRIMARY KEY, affected_from DATE, reason VARCHAR NOT NULL, status VARCHAR NOT NULL, attempt_count INTEGER NOT NULL, last_error VARCHAR, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, completed_at TIMESTAMP, CHECK((status IN ('pending', 'completed'))), CHECK((attempt_count >= 0)));;
CREATE TABLE limit_ladder_snapshot(snapshot_id VARCHAR PRIMARY KEY, trade_date DATE NOT NULL, rule_version VARCHAR NOT NULL, computed_at TIMESTAMP NOT NULL, stock_count INTEGER NOT NULL, has_approx_st BOOLEAN NOT NULL, coverage_json VARCHAR NOT NULL, window_metadata_json VARCHAR DEFAULT('{}') NOT NULL, source_version VARCHAR NOT NULL, st_input_version VARCHAR, CHECK((stock_count >= 0)));;
CREATE TABLE limit_ladder_snapshot_aggregate(snapshot_id VARCHAR, group_type VARCHAR, group_key VARCHAR, group_name VARCHAR NOT NULL, stock_count INTEGER NOT NULL, CHECK((group_type IN ('industry', 'concept'))), CHECK((stock_count >= 0)), PRIMARY KEY(snapshot_id, group_type, group_key));;
CREATE TABLE limit_ladder_snapshot_concept(snapshot_id VARCHAR, code VARCHAR, board_code VARCHAR, board_name VARCHAR NOT NULL, source_version VARCHAR NOT NULL, PRIMARY KEY(snapshot_id, code, board_code));;
CREATE TABLE limit_ladder_snapshot_state(trade_date DATE PRIMARY KEY, status VARCHAR NOT NULL, current_snapshot_id VARCHAR, last_success_at TIMESTAMP, task_id VARCHAR, rule_version VARCHAR NOT NULL, upstream_fingerprint VARCHAR, st_input_version VARCHAR, failure_summary VARCHAR, invalid_reason VARCHAR, updated_at TIMESTAMP NOT NULL, CHECK((status IN ('calculating', 'valid', 'invalid', 'recalculating', 'failed'))));;
CREATE TABLE limit_ladder_snapshot_stock(snapshot_id VARCHAR, code VARCHAR, "name" VARCHAR NOT NULL, board VARCHAR NOT NULL, price_limit_pct DOUBLE NOT NULL, is_st BOOLEAN NOT NULL, st_quality VARCHAR NOT NULL, st_source VARCHAR NOT NULL, is_one_word BOOLEAN NOT NULL, consecutive_days INTEGER NOT NULL, amount DOUBLE NOT NULL, industry_name VARCHAR NOT NULL, industry_board_code VARCHAR, source_version VARCHAR NOT NULL, CHECK((price_limit_pct > 0)), CHECK((st_quality IN ('accurate', 'approximate'))), CHECK((consecutive_days >= 1)), CHECK((isfinite(amount) AND (amount >= 0))), PRIMARY KEY(snapshot_id, code));;
CREATE TABLE limit_ladder_snapshot_window_metric(snapshot_id VARCHAR, code VARCHAR, window_days INTEGER, window_limit_up_days INTEGER NOT NULL, window_return_pct DOUBLE, window_start_date DATE NOT NULL, actual_trade_days INTEGER NOT NULL, source_version VARCHAR NOT NULL, CHECK((window_days IN (10, 20, 31, 60))), CHECK((window_limit_up_days >= 0)), CHECK((actual_trade_days > 0)), PRIMARY KEY(snapshot_id, code, window_days));;
CREATE TABLE scheduled_job(id VARCHAR PRIMARY KEY, "name" VARCHAR, task_type VARCHAR, params VARCHAR, freq_type VARCHAR, freq_config VARCHAR, trigger_mode VARCHAR, dependency_job_id VARCHAR, dependency_order INTEGER, dependency_condition VARCHAR, dependency_delay VARCHAR, retry_config VARCHAR, trading_day_only BOOLEAN, enabled BOOLEAN, last_run_at TIMESTAMP, last_task_id VARCHAR, created_at TIMESTAMP, updated_at TIMESTAMP);;
CREATE TABLE scheduled_job_dependency(upstream_job_id VARCHAR, downstream_job_id VARCHAR, dependency_order INTEGER NOT NULL, PRIMARY KEY(upstream_job_id, downstream_job_id));;
CREATE TABLE scheduled_trigger_event(id VARCHAR PRIMARY KEY, chain_id VARCHAR, source_task_id VARCHAR, source_attempt INTEGER, source_status VARCHAR, target_job_id VARCHAR, trigger_kind VARCHAR, trigger_condition VARCHAR, retry_count INTEGER, dispatch_order INTEGER DEFAULT(0) NOT NULL, due_at TIMESTAMP, dispatched_at TIMESTAMP, status VARCHAR, task_id VARCHAR, job_snapshot VARCHAR, message VARCHAR, created_at TIMESTAMP, updated_at TIMESTAMP);;
CREATE TABLE score_profile(id VARCHAR PRIMARY KEY, "name" VARCHAR, "version" INTEGER, items VARCHAR, grade_thresholds VARCHAR, include_st BOOLEAN DEFAULT(CAST('t' AS BOOLEAN)) NOT NULL, is_preset BOOLEAN, created_at TIMESTAMP, updated_at TIMESTAMP);;
CREATE TABLE score_profile_version(id VARCHAR, "version" INTEGER, "name" VARCHAR, items VARCHAR, grade_thresholds VARCHAR, include_st BOOLEAN DEFAULT(CAST('t' AS BOOLEAN)) NOT NULL, saved_at TIMESTAMP, PRIMARY KEY(id, "version"));;
CREATE TABLE score_result(trade_date DATE, model_id VARCHAR, code VARCHAR, total_score DOUBLE, sub_scores VARCHAR, rank INTEGER, grade VARCHAR, buy_point VARCHAR, risk_flags VARCHAR, PRIMARY KEY(trade_date, model_id, code));;
CREATE TABLE score_snapshot(trade_date DATE, profile_id VARCHAR, profile_version INTEGER, code VARCHAR, total_score DOUBLE, grade VARCHAR, rank INTEGER, sub_scores VARCHAR, PRIMARY KEY(trade_date, profile_id, profile_version, code));;
CREATE TABLE score_snapshot_meta(trade_date DATE, profile_id VARCHAR, profile_version INTEGER, computed_at TIMESTAMP, stale BOOLEAN, n_codes INTEGER, st_input_version VARCHAR, PRIMARY KEY(trade_date, profile_id, profile_version));;
CREATE TABLE screen_profile(id VARCHAR PRIMARY KEY, "name" VARCHAR, "version" INTEGER, expression VARCHAR, params VARCHAR, is_preset BOOLEAN, created_at TIMESTAMP, updated_at TIMESTAMP);;
CREATE TABLE screen_profile_version(id VARCHAR, "version" INTEGER, "name" VARCHAR, expression VARCHAR, saved_at TIMESTAMP, PRIMARY KEY(id, "version"));;
CREATE TABLE screen_result(run_date DATE, profile_id VARCHAR, code VARCHAR, hit BOOLEAN, "matched" VARCHAR, "snapshot" VARCHAR, PRIMARY KEY(run_date, profile_id, code));;
CREATE TABLE stock_basic(code VARCHAR PRIMARY KEY, "name" VARCHAR, exchange VARCHAR, board VARCHAR, list_date DATE, delist_date_manual BOOLEAN DEFAULT(CAST('f' AS BOOLEAN)), delist_date_reported DATE, delist_date DATE, total_share BIGINT, float_share BIGINT, total_share_date DATE, float_share_date DATE, industry VARCHAR, concept VARCHAR, price_limit_pct DOUBLE);;
CREATE TABLE stock_board_correlation(code VARCHAR, board_type VARCHAR, board_code VARCHAR NOT NULL, score DOUBLE NOT NULL, corr_20 DOUBLE NOT NULL, corr_60 DOUBLE NOT NULL, sample_20 INTEGER NOT NULL, sample_60 INTEGER NOT NULL, confidence VARCHAR NOT NULL, benchmark_code VARCHAR NOT NULL, benchmark_fallback BOOLEAN DEFAULT(CAST('f' AS BOOLEAN)) NOT NULL, as_of_date DATE, computed_at TIMESTAMP NOT NULL, algorithm_version VARCHAR NOT NULL, CHECK((board_type IN ('industry', 'concept'))), CHECK((isfinite(score) AND (score BETWEEN -1 AND 1))), CHECK((isfinite(corr_20) AND (corr_20 BETWEEN -1 AND 1))), CHECK((isfinite(corr_60) AND (corr_60 BETWEEN -1 AND 1))), CHECK((sample_20 >= 15)), CHECK((sample_60 >= 40)), CHECK((confidence IN ('high', 'medium', 'low'))), PRIMARY KEY(code, board_type, as_of_date));;
CREATE TABLE stock_board_correlation_state(code VARCHAR, as_of_date DATE, computed_at TIMESTAMP NOT NULL, algorithm_version VARCHAR NOT NULL, benchmark_code VARCHAR NOT NULL, benchmark_fallback BOOLEAN DEFAULT(CAST('f' AS BOOLEAN)) NOT NULL, has_industry_champion BOOLEAN DEFAULT(CAST('f' AS BOOLEAN)) NOT NULL, has_concept_champion BOOLEAN DEFAULT(CAST('f' AS BOOLEAN)) NOT NULL, industry_empty_reason VARCHAR, industry_max_sample_20 INTEGER, industry_max_sample_60 INTEGER, concept_empty_reason VARCHAR, concept_max_sample_20 INTEGER, concept_max_sample_60 INTEGER, CHECK(((industry_empty_reason IS NULL) OR (industry_empty_reason IN ('no_candidates', 'insufficient_samples', 'invalid_correlation')))), CHECK(((industry_max_sample_20 IS NULL) OR (industry_max_sample_20 BETWEEN 0 AND 20))), CHECK(((industry_max_sample_60 IS NULL) OR (industry_max_sample_60 BETWEEN 0 AND 60))), CHECK(((concept_empty_reason IS NULL) OR (concept_empty_reason IN ('no_candidates', 'insufficient_samples', 'invalid_correlation')))), CHECK(((concept_max_sample_20 IS NULL) OR (concept_max_sample_20 BETWEEN 0 AND 20))), CHECK(((concept_max_sample_60 IS NULL) OR (concept_max_sample_60 BETWEEN 0 AND 60))), PRIMARY KEY(code, as_of_date));;
CREATE TABLE stock_group(id VARCHAR PRIMARY KEY, "name" VARCHAR, group_date DATE, description VARCHAR, color VARCHAR, is_default BOOLEAN, created_at TIMESTAMP, updated_at TIMESTAMP);;
CREATE TABLE stock_group_member(group_id VARCHAR, code VARCHAR, add_date DATE, note VARCHAR, PRIMARY KEY(group_id, code));;
CREATE TABLE stock_intraday_bar(code VARCHAR, trade_date DATE, "timestamp" TIMESTAMP, open DOUBLE, high DOUBLE NOT NULL, low DOUBLE NOT NULL, "close" DOUBLE NOT NULL, volume DOUBLE NOT NULL, amount DOUBLE NOT NULL, "source" VARCHAR NOT NULL, fetched_at TIMESTAMP NOT NULL, PRIMARY KEY(code, trade_date, "timestamp"));;
CREATE TABLE stock_intraday_coverage(code VARCHAR, trade_date DATE, point_count INTEGER DEFAULT(0), status VARCHAR DEFAULT('missing'), "source" VARCHAR, fetched_at TIMESTAMP, attempted_at TIMESTAMP, failure_reason VARCHAR, diagnostics VARCHAR, revision VARCHAR, PRIMARY KEY(code, trade_date));;
CREATE TABLE stock_intraday_monitor(code VARCHAR PRIMARY KEY, monitoring_start DATE NOT NULL, created_at TIMESTAMP DEFAULT(current_timestamp) NOT NULL);;
CREATE TABLE stock_intraday_source_state(code VARCHAR, "source" VARCHAR, checked_at TIMESTAMP NOT NULL, outcome VARCHAR NOT NULL, failure_reason VARCHAR, evidence VARCHAR, task_id VARCHAR, PRIMARY KEY(code, "source"));;
CREATE TABLE stock_share_capital_daily(code VARCHAR, trade_date DATE, total_share BIGINT, float_share BIGINT, total_source VARCHAR, float_source VARCHAR, total_effective_date DATE, float_effective_date DATE, total_available_date DATE, float_available_date DATE, total_mv_eligible BOOLEAN, updated_at TIMESTAMP DEFAULT(current_timestamp), PRIMARY KEY(code, trade_date));;
CREATE TABLE stock_share_capital_event(event_id VARCHAR PRIMARY KEY, code VARCHAR, "source" VARCHAR, effective_date DATE, available_date DATE, date_basis VARCHAR, change_reason VARCHAR, total_share BIGINT, float_share BIGINT, raw_payload VARCHAR, active BOOLEAN, first_seen_at TIMESTAMP, last_seen_at TIMESTAMP);;
CREATE TABLE stock_share_capital_history(code VARCHAR, trade_date DATE, total_share BIGINT, float_share BIGINT, total_source VARCHAR, float_source VARCHAR, total_effective_date DATE, float_effective_date DATE, total_available_date DATE, float_available_date DATE, total_basis VARCHAR, float_basis VARCHAR, total_event_id VARCHAR, float_event_id VARCHAR, total_mv DOUBLE, float_mv DOUBLE, total_mv_source VARCHAR, float_mv_source VARCHAR, updated_at TIMESTAMP DEFAULT(current_timestamp), PRIMARY KEY(code, trade_date));;
CREATE TABLE stock_special_trading_day(code VARCHAR, trade_date DATE, event_type VARCHAR NOT NULL, announcement_date DATE NOT NULL, source_ref VARCHAR NOT NULL, note VARCHAR NOT NULL, active BOOLEAN NOT NULL, task_id VARCHAR NOT NULL, updated_at TIMESTAMP NOT NULL, CHECK((event_type IN ('delisting_first_day', 'resumption_no_limit'))), CHECK((announcement_date <= trade_date)), PRIMARY KEY(code, trade_date));;
CREATE TABLE stock_st_status_daily(code VARCHAR, trade_date DATE, is_st BOOLEAN NOT NULL, "source" VARCHAR NOT NULL, source_ref VARCHAR, quality VARCHAR NOT NULL, captured_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, CHECK((quality IN ('accurate', 'approximate'))), PRIMARY KEY(code, trade_date));;
CREATE TABLE stock_st_status_date_revision(trade_date DATE PRIMARY KEY, revision BIGINT NOT NULL, updated_at TIMESTAMP NOT NULL, CHECK((revision > 0)));;
CREATE TABLE stock_st_status_history(version_id VARCHAR PRIMARY KEY, code VARCHAR NOT NULL, trade_date DATE NOT NULL, old_is_st BOOLEAN, new_is_st BOOLEAN NOT NULL, old_source VARCHAR, new_source VARCHAR NOT NULL, old_source_ref VARCHAR, new_source_ref VARCHAR, old_quality VARCHAR, new_quality VARCHAR NOT NULL, change_reason VARCHAR NOT NULL, changed_at TIMESTAMP NOT NULL, task_id VARCHAR, CHECK(((old_quality IS NULL) OR (old_quality IN ('accurate', 'approximate')))), CHECK((new_quality IN ('accurate', 'approximate'))));;
CREATE TABLE stock_st_status_refresh_state(scope_key VARCHAR PRIMARY KEY, status VARCHAR NOT NULL, task_id VARCHAR, target_count INTEGER DEFAULT(0) NOT NULL, date_start DATE, date_end DATE, last_error VARCHAR, updated_at TIMESTAMP NOT NULL, CHECK((status IN ('refreshing', 'ready', 'failed'))));;
CREATE TABLE stock_suspension(code VARCHAR, trade_date DATE, confirmed_at TIMESTAMP, "source" VARCHAR, task_id VARCHAR);;
CREATE TABLE task_log(id BIGINT, task_id VARCHAR, seq INTEGER, ts TIMESTAMP, "level" VARCHAR, message VARCHAR);;
CREATE TABLE trade_calendar(trade_date DATE PRIMARY KEY, is_open BOOLEAN);;
CREATE TABLE trade_profile(id VARCHAR PRIMARY KEY, "name" VARCHAR, "version" INTEGER, buy_tree VARCHAR, sell_tree VARCHAR, backstop VARCHAR, is_preset BOOLEAN, created_at TIMESTAMP, updated_at TIMESTAMP);;
CREATE TABLE trade_profile_version(id VARCHAR, "version" INTEGER, "name" VARCHAR, buy_tree VARCHAR, sell_tree VARCHAR, backstop VARCHAR, saved_at TIMESTAMP, PRIMARY KEY(id, "version"));;
CREATE TABLE training_round(session_id VARCHAR, seq INTEGER, code VARCHAR, start_date DATE, end_date DATE, window_days INTEGER, base_factor DOUBLE, price_limit_pct DOUBLE, cursor_date DATE, cursor_idx INTEGER, status VARCHAR, cash DOUBLE, pos_shares BIGINT, pos_cost DOUBLE, pos_avg_price DOUBLE, pending VARCHAR, realized_pnl DOUBLE, round_return DOUBLE, benchmark_return DOUBLE, final_equity DOUBLE, PRIMARY KEY(session_id, seq));;
CREATE TABLE training_session(id VARCHAR PRIMARY KEY, user_id VARCHAR, "mode" VARCHAR, range_start DATE, range_end DATE, n_rounds INTEGER, window_days INTEGER, initial_capital DOUBLE, filters VARCHAR, fee_enabled BOOLEAN, status VARCHAR, cur_round INTEGER, total_return DOUBLE, score DOUBLE, grade VARCHAR, win_rate DOUBLE, max_drawdown DOUBLE, n_trades INTEGER, review_note VARCHAR, created_at TIMESTAMP, completed_at TIMESTAMP);;
CREATE TABLE training_trade(session_id VARCHAR, round_seq INTEGER, seq INTEGER, side VARCHAR, decide_date DATE, fill_date DATE, rel_day INTEGER, price DOUBLE, hands INTEGER, shares BIGINT, amount DOUBLE, fee DOUBLE, pnl DOUBLE, return_pct DOUBLE, reason VARCHAR, auto_close BOOLEAN, PRIMARY KEY(session_id, round_seq, seq));;
CREATE INDEX idx_limit_ladder_invalidation_pending ON limit_ladder_invalidation_outbox(status, created_at);;
CREATE INDEX idx_limit_ladder_snapshot_date ON limit_ladder_snapshot(trade_date, computed_at);;
CREATE INDEX idx_limit_ladder_stock_snapshot ON limit_ladder_snapshot_stock(snapshot_id, consecutive_days);;
CREATE INDEX idx_st_status_daily_date ON stock_st_status_daily(trade_date, updated_at);;
CREATE INDEX idx_st_status_history_code_date ON stock_st_status_history(code, trade_date, changed_at);;
CREATE INDEX idx_st_status_history_date ON stock_st_status_history(trade_date, changed_at);;
